export const fetchResorts = async () => {
  try {
    const response = await axios.get(`${API_URL}/ski-resorts`);
    return response.data; 
  } catch (error) {
    console.error('Error fetching resorts:', error.message); // Detailed logging
    return []; 
  }
};
